          Overflow_o <= 1'b1;
          Zero_o <= 1'b0;
        end
        else begin
          count <= count + 1;
          Overflow_o <= 1'b0;
          Zero_o <= (count == 16'h0000);
        end
      end
      else begin
        if (count == 16'h0000) begin
          count <= 16'hFFFF;
          Overflow_o <= 1'b0;
          Zero_o <= 1'b1;
        end
        else begin
          count <= count - 1;
          Overflow_o <= (count == 16'hFFFF);
          Zero_o <= 1'b0;
        end
      end
    end
    D_o <= count;
  end

