module top_module(
	input 	clk,	  				
	input	wr,						
	input 	reset, 					
	input 	tlo,					
	input	thi,		 			
	input	tcr,					
	input 	[7:0] data_in,			
	output 	[7:0] data_out,			
	input	eclk,	  				
	output	tmra_ovf,				
	output	spmode,					
	output	irq						
);reg		[15:0] tmr;				
reg		[7:0] tmlh;				
reg		[7:0] tmll;				
reg		[6:0] tmcr;				
reg		forceload;				
wire	oneshot;				
wire	start;					
reg		thi_load;    			
wire	reload;					
wire	zero;					
wire	underflow;				
wire	count;					


assign count = eclk;


always @(posedge clk)
	if (reset)	
		tmcr[6:0] <= 7'd0;
	else if (tcr && wr)	
		tmcr[6:0] <= {data_in[6:5],1'b0,data_in[3:0]};
	else if (thi_load && oneshot)	
		tmcr[0] <= 1'd1;
	else if (underflow && oneshot) 
		tmcr[0] <= 1'd0;

always @(posedge clk)
	forceload <= tcr & wr & data_in[4];	

assign oneshot = tmcr[3];		
assign start = tmcr[0];			
assign spmode = tmcr[6];		


always @(posedge clk)
	if (reset)
		tmll[7:0] <= 8'b1111_1111;
	else if (tlo && wr)
		tmll[7:0] <= data_in[7:0];

always @(posedge clk)
	if (reset)
		tmlh[7:0] <= 8'b1111_1111;
	else if (thi && wr)
		tmlh[7:0] <= data_in[7:0];


always @(posedge clk)
	thi_load <= thi & wr & (~start | oneshot);


assign reload = thi_load | forceload | underflow;


always @(posedge clk)
	if (reset)
		tmr[15:0] <= 16'hFF_FF;
	else if (reload)
		tmr[15:0] <= {tmlh[7:0],tmll[7:0]};
	else if (start && count)
		tmr[15:0] <= tmr[15:0] - 16'd1;


assign zero = ~|tmr;		


assign underflow = zero & start & count;


assign tmra_ovf = underflow;


assign irq = underflow;


assign data_out[7:0] = ({8{~wr&tlo}} & tmr[7:0]) 
					| ({8{~wr&thi}} & tmr[15:8])
					| ({8{~wr&tcr}} & {1'b0,tmcr[6:0]});		

endmodule

