module top_module(
    input [31:0] desired_duty_cycle_1000,
    input [31:0] clk_period_1000,
    input clk,
    input reset,
    output reg LOCKED,
    output reg fail
);reg [31:0] high_count;
    reg [31:0] low_count;
    reg [31:0] total_count;
    reg [31:0] duty_cycle_1000;

    always @(posedge clk or negedge reset) begin
        if (reset == 1'b0) begin
            high_count <= 0;
            low_count <= 0;
            total_count <= 0;
            duty_cycle_1000 <= 0;
            LOCKED <= 0;
            fail <= 0;
        end else begin
            if (clk == 1'b1) begin
                high_count <= high_count + 1;
            end else begin
                low_count <= low_count + 1;
            end
            total_count <= total_count + 1;
            if (total_count == clk_period_1000 - 1) begin
                duty_cycle_1000 <= high_count * 1000 / total_count;
                if (duty_cycle_1000 >= desired_duty_cycle_1000 - 1 && duty_cycle_1000 <= desired_duty_cycle_1000 + 1) begin
                    LOCKED <= 1;
                    fail <= 0;
                end else begin
                    LOCKED <= 0;
                    fail <= 1;
                end
                high_count <= 0;
                low_count <= 0;
                total_count <= 0;
            end
        end
    end

endmodule

