module top_module(
  input data_in,
  input clk_source,
  input clk_dest,
  output reg data_out
);reg [1:0] source_ff;
  reg [1:0] dest_ff;

  always @(posedge clk_source) begin
    source_ff <= {source_ff[0], data_in};
  end

  always @(posedge clk_dest) begin
    dest_ff <= {dest_ff[0], source_ff[1]};
  end

  reg [1:0] metastable_ff;

  always @(posedge clk_dest) begin
    if (dest_ff[1] == metastable_ff[0]) begin
      metastable_ff <= {dest_ff[1], dest_ff[1]};
    end else begin
      metastable_ff <= {dest_ff[1], metastable_ff[1]};
    end
  end

  always @(posedge clk_dest) begin
    data_out <= metastable_ff[1];
  end

endmodule

