module top_module(
    output reg [2:0] alucontrol,
    input [5:0] funct,
    input [1:0] aluop
    );always @ (aluop or funct) begin
        case(aluop)
            2'b00:  alucontrol <= 3'b010; 
            2'b01:  alucontrol <= 3'b110; 
