module top_module(wr_rst_busy,
    dout,
    empty,
    full,
    clk,
    din,
    rst,
    rd_en,
    wr_en);output reg wr_rst_busy; // Change to reg to allow assignment in always block
  output reg [63:0] dout; // Change to reg to allow assignment in always block
  output empty;
  output full;
  input clk;
  input [63:0] din;
  input rst;
  input rd_en;
  input wr_en;

  reg [3:0] r_ptr; // Change to reg for pointer
  reg [3:0] w_ptr; // Change to reg for pointer
  reg [15:0] fifo_mem [0:15]; // Remains reg array
  reg [15:0] count; // Change to reg for count
  reg [15:0] next_count;
  reg [3:0] new_data; // Use 4 bits for data to match data width
  reg [3:0] old_data; // Use 4 bits for data to match data width
  reg [3:0] next_r_ptr; // Change to reg
  reg [3:0] next_w_ptr; // Change to reg

  assign empty = (count == 0);
  assign full = (count == 16);

  assign next_r_ptr = (empty) ? r_ptr : r_ptr + 1;
  assign next_w_ptr = (full) ? w_ptr : w_ptr + 1;

  // Adjusting new_data and old_data to correctly mirror data width
  assign new_data = din[15:0]; // Only use the lower 16 bits for input data
  assign old_data = fifo_mem[r_ptr];

  assign next_count = count + wr_en - rd_en; // Do not subtract rst from count here

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      wr_rst_busy <= 1;
      count <= 0;
      r_ptr <= 0;
      w_ptr <= 0;
      fifo_mem[0] <= 16'h0; // Clear only first element, not the entire array
    end else begin
      wr_rst_busy <= (wr_en && full) || (rd_en && empty);
      if (wr_en && !full) begin
        fifo_mem[w_ptr] <= new_data; // Correctly assign new_data
        count <= next_count;
        w_ptr <= next_w_ptr;
      end
      if (rd_en && !empty) begin
        dout <= {fifo_mem[r_ptr]}; // Assign data to dout
        count <= next_count; // Update the count correctly
        r_ptr <= next_r_ptr;
      end
    end
  end
endmodule

