    output reg lt,       // Changed to output reg
    output reg eq        // Changed to output reg
);reg [7:0] a_reg, b_reg;
reg [2:0] stage;

always @(posedge clk) begin
    case (stage)
        0: begin
            a_reg <= a;
            b_reg <= b;
            stage <= 1;
        end
        1: begin
            a_reg <= a_reg;
            b_reg <= b_reg;
