module top_module(I1, wr_clk, I2, rd_clk, I3, I4, I5, I6, Q, O1, O2, O3, O4, O5);parameter DEPTH = 16;

input [2:0] I1;
input wr_clk;
input [3:0] I2;
input rd_clk;
input [3:0] I3;
input I4;
input I5;
input [3:0] I6;

output [2:0] Q;
output [3:0] O1;
output O2;
output [3:0] O3;
output O4;
output O5;

reg [2:0] Q_reg;
reg [3:0] wr_ptr_reg;
reg [3:0] rd_ptr_reg;
wire [3:0] wr_ptr_next;
wire [3:0] rd_ptr_next;
wire [2:0] Q_next;
reg empty;
reg full;
reg almost_full;

assign Q = Q_reg;
assign O1 = wr_ptr_reg;
assign O2 = empty;
assign O3 = rd_ptr_reg;
assign O4 = full;
assign O5 = almost_full;

// Write pointer logic
always @(posedge wr_clk) begin
    if (I4) begin
        wr_ptr_reg <= 0;
    end else begin
        wr_ptr_reg <= wr_ptr_next;
    end
end

assign wr_ptr_next = (wr_ptr_reg == (DEPTH - 1)) ? 0 : wr_ptr_reg + 1;

// Read pointer logic
always @(posedge rd_clk) begin
    if (I5) begin
        rd_ptr_reg <= 0;
    end else begin
        rd_ptr_reg <= rd_ptr_next;
    end
end

assign rd_ptr_next = (rd_ptr_reg == (DEPTH - 1)) ? 0 : rd_ptr_reg + 1;

// Data logic
always @(posedge wr_clk) begin
    full <= (wr_ptr_next == rd_ptr_reg);
end

always @(posedge rd_clk) begin
    empty <= (wr_ptr_reg == rd_ptr_reg);
end

always @(posedge wr_clk) begin
    almost_full <= (wr_ptr_next == (DEPTH - 2));
end

always @(posedge wr_clk) begin
    if (wr_ptr_next == rd_ptr_reg) begin
        Q_reg <= Q_next;
    end
end

assign Q_next = (wr_ptr_next == rd_ptr_reg) ? I1 : Q_reg;

endmodule

