module fsm_logic (
        input clk,
        input reset,
        input g,
        output reg y);parameter A=0, B=1, C=2, D=3;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= A;
		else 
			state <= next;

	always_comb begin
		case(state)
			A: next = g ? C : B;
			B: next = g ? A : D;
			C: next = g ? D : A;
			D: next = g ? C : B;
			default: next = 'x;
		endcase
	end

	assign y = (state == A || state == C);

endmodule

