module top_module(
  input clk,
  input reset,
  input [3:0] data,
  output reg match
);parameter S0 = 2'b00;
  parameter S1 = 2'b01;
  parameter S2 = 2'b10;
  parameter S3 = 2'b11;

  reg [1:0] state;

  always @ (posedge clk or negedge reset) begin
    if (reset == 0) begin
      state <= S0;
      match <= 0;
    end
    else begin
      case (state)
        S0: begin
          if (data[2:0] == 3'b001) begin
            state <= S1;
          end
          else begin
            state <= S0;
          end
        end
        S1: begin
          if (data[2:0] == 3'b010) begin
            state <= S2;
          end
          else begin
            state <= S0;
          end
        end
        S2: begin
          if (data[2:0] == 3'b100) begin
            state <= S3;
            match <= 1;
          end
          else begin
            state <= S0;
          end
        end
        S3: begin
          state <= S0;
        end
      endcase
    end
  end

endmodule

