description:
Design a synchronous finite state machine that computes the two's complement of a binary input over clock cycles. The module has an input bit `x` and a reset signal `rst`. When the system is in the reset state (S0), it outputs the value of `x`. Transitioning to state S1, the output `z` is set to the logical NOT of `x`, effectively implementing the two's complement operation. The machine maintains this state until the reset is activated, allowing for the toggling of the output based on the input. The design also ensures that the output is reset to zero under default conditions.
module top_module(x, clk, rst, z            
    );

code:
module top_module(x, clk, rst, z            
    );input x, clk, rst;
output reg z;
parameter S0 = 0, S1 = 1;        
reg [0:1]  PS, NS;
always @ (posedge clk)       
if (rst) begin
    PS <= S0;       
    NS <= S0;       
   end
else begin
    PS <= NS;       
    end

always @(PS or x)   
    case (PS)
    S0 : begin                  
        z <= x;
        NS <= S1;              
        end
    S1 : begin
        z <= !x;               
        NS <= S1;
        end
    default: begin               
        NS <= S0;
        z <= 0;
        end
    endcase


endmodule

