  s1=5'b00010, 
  s2=5'b00100, 
  s3=5'b01000, 
  s4=5'b10000; 
 reg [4:0] stat_reg,next_reg; 
 always @(posedge clk,posedge rst) 
  if(rst) 
  stat_reg<=s0; 
 else 
  stat_reg<=next_reg; 
 always@(*) 
  case(stat_reg) 
  s0: if(in) next_reg=s1; 
