  else next_reg=s2; 
  s2: if(in) next_reg=s3; 
  else next_reg=s1; 
  s3: if(in) next_reg=s4; 
  else next_reg=s0; 
  s4: if(in) next_reg=s1; 
  else next_reg=s0; 
  default: next_reg=s0; 
  endcase 
 assign detctd= in?(stat_reg==s4):1'b0; 
 endmodule

