module top_module (
        input clk,
        input areset,
        input button_pressed,
        input button_released,
        output reg bell);parameter Idle = 1'b0, Ring = 1'b1;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Idle;
		else begin
			case (state)
				Idle: state <= button_pressed ? Ring : Idle;
				Ring: state <= button_released ? Idle : Ring;
			endcase
		end
	end

	assign bell = (state == Ring);

endmodule

