module pedestrian_crossing (
	input clk,
	input resetn,
	input button,
	output reg walk);

	parameter WAIT=0, WALK=1, DONOT_WALK=2;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= WAIT;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			WAIT: next_state = button ? WALK : WAIT;
			WALK: next_state = DONOT_WALK;
			DONOT_WALK: next_state = WAIT;
			default: next_state = WAIT;
		endcase
	end

	always @(state) begin
		case (state)
			WALK: walk = 1;
			default: walk = 0;
		endcase
	end
endmodule

