            @(negedge clk);
            load = 1;
            data = 512'b0;
            @(posedge clk);
            #1;
            load = 0;
        end
        endtask
    task testcase001;

        begin
            @(negedge clk);
            load = 1;
            data = 512'h55555555555555555555555555555555555555555555555555555555555555555555555555555555555555555555555555555555555555555555555555555555;
            @(posedge clk);
            #1;
            #1;

            check_outputs(data);
        end
        endtask

    task testcase002;

        begin
            reset_dut();
            @(negedge clk);
            load = 1;
            data = 512'h8;
            @(posedge clk);
            #1;
            load = 0;
            @(posedge clk);
            #1;

            #1;


            check_outputs(512'h1C);
        end
        endtask

    task testcase003;

        begin
            reset_dut();
            @(negedge clk);
            load = 1;
            data = 512'h8;
            @(posedge clk);
            #1;
            load = 0;
            repeat(2) @(posedge clk);
            #1;
            #1;

            check_outputs(512'h36);
        end
        endtask

    task testcase004;

        begin
            reset_dut();
            @(negedge clk);
            load = 1;
            data = 512'h1;
            @(posedge clk);
            #1;
            load = 0;
            @(posedge clk);
            #1;
            #1;

            check_outputs(512'h3);
        end
        endtask

    task testcase005;

        reg [511:0] expected;
        begin
            reset_dut();
            @(negedge clk);
            load = 1;
            data = (512'h1 << 511);
            @(posedge clk);
            #1;
            load = 0;
            @(posedge clk);
            #1;
            expected = (512'h1 << 511) | (512'h1 << 510);
            #1;

            check_outputs(expected);
        end
        endtask

    task testcase006;

        begin
            reset_dut();
            @(negedge clk);
            load = 1;
            data = 512'h0;
            @(posedge clk);
            #1;
            load = 0;
            repeat(5) @(posedge clk);
            #1;
            #1;

            check_outputs(512'h0);
        end
        endtask

    task testcase007;

        reg [511:0] expected;
        begin
            reset_dut();
            @(negedge clk);
            load = 1;
            data = ~512'h0;
            @(posedge clk);
            #1;
            load = 0;
            @(posedge clk);
            #1;
            expected = (512'h1 << 511) | 512'h1;
            #1;

            check_outputs(expected);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("top_module Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();
        testcase007();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [511:0] expected_q;
        begin
            if (expected_q === (expected_q ^ q ^ expected_q)) begin
                $display("PASS");
                $display("  Outputs: q=%h",
                         q);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: q=%h",
                         expected_q);
                $display("  Got:      q=%h",
                         q);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,clk, data, load, q);
    end

endmodule
